def prior_ux30_bytes(path,raw):
 name=Path(path).name
 if name not in FACTS or b'data-copy30='not in raw:return raw
 context='UX30 UX29 UX28 ART28 ART35 UX27 complete source'
 assert hashlib.sha256(raw).hexdigest()==FACTS[name]['after'],context+' changed beyond the copy contract: '+name
 text=raw.decode()
 for at,before,after in reversed(OPERATIONS[name]):
  assert text[at:at+len(after)]==after,context+' exact display span'
  text=text[:at]+before+text[at+len(after):]
 assert hashlib.sha256(text.encode()).hexdigest()==FACTS[name]['before'],context+' original whole file'
 return text.encode()
def normalize_ux30(name,text):return prior_ux30_bytes(name,text.encode()).decode()

def validate_ux30(root):
 root=Path(root).resolve()
 if not(root/LEDGER).exists():
  assert not any((root/'web/src'/n).exists()and b'data-copy30='in(root/'web/src'/n).read_bytes()for n in FACTS),'UX30 unrecorded copy evolution'
  return set(),0
 def local(n):
  p=root/n;assert p.is_file()and not p.is_symlink()and p.resolve().is_relative_to(root),'UX30 local source';return p
 m=json.loads(local(LEDGER).read_text());assert m['format']=='chenyuan-primary-copy-ux30'and type(m['version'])is int and m['version']==1 and m['userAcceptance']is False,'UX30 scope/acceptance'
 assert m['budgets']==BUDGETS and all(type(v)is int for v in m['budgets'].values()),'UX30 original caps'
 assert [r['path']for r in m['files']]==['web/src/'+n for n in FACTS]and m['sourceReferences']==REFS,'UX30 exact members'
 assert [r['path']for r in m['baselines']]==[f['baseline']for f in FACTS.values()],'UX30 exact originals'
 assert json.loads(local('art/redesign/ux30-display-edits.json').read_text())=={name:[[before,after]for _,before,after in rows]for name,rows in OPERATIONS.items()},'UX30 exact published copy changes'
 for row in m['files']+m['baselines']:
  data=local(row['path']).read_bytes();assert len(data)==row['bytes']and hashlib.sha256(data).hexdigest()==row['sha256'],'UX30 actual source facts'
 for name,f in FACTS.items():
  path='web/src/'+name;raw=local(path).read_bytes();before=local(f['baseline']).read_bytes();assert hashlib.sha256(before).hexdigest()==f['before']and prior_ux30_bytes(name,raw)==before,'UX30 original source inverse'
  assert len(raw)==f['bytes']and raw.count(b'data-copy30=')==1,'UX30 actual copy consumer'
  script=lambda data:re.search(rb'<script setup.*?</script>',data,re.S).group()
  assert script(raw)==script(before),'UX30 original controller untouched'
 for name,(field,cap)in GROUPS.items():
  old=json.loads(local('art/redesign/'+name+'.json').read_text());value=old.get('budgets',{}).get(field,old.get(field));assert value==cap,'UX30 original regional cap'
  assert sum(local(r['path']).stat().st_size for r in old['files'])<=cap,'UX30 actual regional bytes'
 assert local('web/src/App.vue').stat().st_size<=159635 and local('web/src/RecoveryRitual.vue').stat().st_size<=9658,'UX30 actual parent cap'
 assert not any('font-size' in after or 'overflow:hidden' in after or 'overflow:clip' in after for rows in OPERATIONS.values()for _,_,after in rows),'UX30 cannot shrink or clip'
 for ref in REFS:local(ref)
 return{LEDGER,*REFS,*[r['path']for r in m['files']],*[r['path']for r in m['baselines']]},sum(local(r['path']).stat().st_size for r in m['files'])
